    10→export const ConfirmIdentity: FC<
    11→  NativeStackScreenProps<Routes, "confirmIdentity">
    12→> = ({ navigation }) => {
    13→  const [loading, setLoading] = useState(true);
    14→  const [hasOtherDevices, setHasOtherDevices] = useState(false);
    15→  const [recoveryEnabled, setRecoveryEnabled] = useState(false);
    16→
    17→  useEffect(() => {
    18→    const checkSituation = async () => {
    19→      try {
    20→        const [otherDevices, recovery] = await Promise.all([
    21→          VerificationService.hasDevicesToVerifyAgainst(),
    22→          EncryptionService.isRecoveryEnabled(),
    23→        ]);
    24→        setHasOtherDevices(otherDevices);
    25→        setRecoveryEnabled(recovery);
    26→      } catch (error) {
    27→        console.error("Failed to check verification situation:", error);
    28→      } finally {
    29→        setLoading(false);
    30→      }
    31→    };
    32→    checkSituation();
    33→  }, []);
    34→
    35→  const showResetOnly = !hasOtherDevices && !recoveryEnabled;
    36→
    37→  return (
    38→    <ScreenLayout>
    39→      <Block flex={1}>
    40→        <Block flex={1} justify="center" align="center" gap={24}>
    41→          <Block gap={12}>
    42→            <Text
    43→              size={TextSize.large}
    44→              textAlign="center"
    45→              font="InstrumentSans-Medium"
    46→            >
    47→              Verify your device
    48→            </Text>
    49→            <Text
    50→              textAlign="center"
    51→              font="InstrumentSans-Regular"
    52→              color={Colors.white50}
    53→            >
    54→              Verify this device to access your encrypted message history and
    55→              set up secure messaging.
    56→            </Text>
    57→          </Block>
    58→
    59→          <Block
    60→            border={{ borderRadius: 12 }}
    61→            background={Colors.white5}
    62→            paddings={[16, 16]}
    63→            gap={12}
    64→          >
    65→            <Block flexDirection="row" align="center" gap={12}>
    66→              <Image
    67→                source={require("assets/icons/info.png")}
    68→                tintColor={Colors.primary}
    69→                width={20}
    70→                height={20}
    71→              />
    72→              <Text color={Colors.white80} size={TextSize.small}>
    73→                Without verification, you won't be able to access messages sent
    74→                before this login.
    75→              </Text>
    76→            </Block>
    77→          </Block>
    78→        </Block>
    79→
    80→        {loading ? (
    81→          <Block align="center" paddings={[20, 0]}>
    82→            <ActivityIndicator color={Colors.primary} />
    83→          </Block>
    84→        ) : (
    85→          <Block gap={12}>
    86→            {hasOtherDevices && (
    87→              <Button.Primary
    88→                onPress={() => navigation.navigate("verifyWithDevice")}
    89→              >
    90→                Verify with Another Device
    91→              </Button.Primary>
    92→            )}
    93→            {recoveryEnabled && (
    94→              <Button.Outline
    95→                onPress={() => navigation.navigate("enterRecoveryKey")}
    96→              >
    97→                Use Recovery Key
    98→              </Button.Outline>
    99→            )}
   100→            {showResetOnly && (
   101→              <Button.Primary
   102→                onPress={() => navigation.navigate("cantConfirm")}
   103→              >
   104→                Reset Identity
   105→              </Button.Primary>
   106→            )}
   107→            {!showResetOnly && (
   108→              <Button.Outline
   109→                onPress={() => navigation.navigate("cantConfirm")}
   110→              >
   111→                Can't confirm identity?
   112→              </Button.Outline>
   113→            )}
   114→          </Block>
   115→        )}
   116→      </Block>
   117→    </ScreenLayout>
   118→  );
   119→};
