    15→
    16→export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
    17→  navigation,
    18→}) => {
    19→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
    20→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
    21→  const hasSeenNotificationsIntro = useAtomValue(
    22→    PushNotificationsAtoms.hasSeenNotificationsIntro,
    23→  );
    24→  const transition = useRef(
    25→    animateParallel(
    26→      { opacity: [0, 1], translateY: [40, 0] },
    27→      { duration: 200 },
    28→    ),
    29→  ).current;
    30→
    31→  useEffect(() => {
    32→    const checkAuthAndNavigate = async () => {
    33→      try {
    34→        // Check if we have stored credentials
    35→        if (AuthService.hasStoredCredentials()) {
    36→          const sessionRestored = await AuthService.restoreSession();
    37→          const isVerified = VerificationService.isDeviceVerified();
    38→          await MatrixCore.refreshRoomList();
    39→
    40→          if (sessionRestored && !isVerified) {
    41→            navigation.replace("confirmIdentity");
    42→            return;
    43→          }
    44→
    45→          if (!hasSeenOnboarding) {
    46→            navigation.replace("onboarding");
    47→            return;
    48→          }
    49→
    50→          if (!hasSeenNotificationsIntro) {
    51→            navigation.replace("notificationsIntro");
    52→            return;
    53→          }
    54→
    55→          //If there is a screen lock pin, navigate to the verify pin screen
    56→          if (screenLockPin && sessionRestored) {
    57→            navigation.replace("verifyPin", { isSettingsScreen: false });
    58→            return;
    59→          }
    60→
    61→          if (sessionRestored) {
    62→            // Check if app was opened from a notification
    63→            const pendingRoomId = NotifeeService.consumePendingRoomId();
    64→            if (pendingRoomId) {
    65→              navigation.reset({
    66→                index: 1,
    67→                routes: [
    68→                  { name: "home" },
    69→                  { name: "room", params: { roomId: pendingRoomId } },
    70→                ],
    71→              });
    72→              return;
    73→            }
    74→
    75→            navigation.replace("home");
    76→            return;
    77→          }
    78→        }
    79→
    80→        await AuthService.initialize(MatrixBaseURL);
    81→        navigation.replace("welcome");
    82→      } catch (error) {
    83→        console.warn("Error during auth check:", error);
    84→        navigation.replace("welcome");
    85→      }
    86→    };
    87→
    88→    transition.start(() => {
    89→      setTimeout(checkAuthAndNavigate, 2000);
    90→    });
    91→  }, [navigation, hasSeenOnboarding, screenLockPin, transition]);
    92→
    93→  return (
    94→    <ScreenLayout>
    95→      <Block
    96→        animations={transition.animations}
    97→        flex={1}
    98→        align="center"
    99→        justify="space-between"
   100→      >
   101→        <Image
   102→          source={require("assets/images/logo.png")}
   103→          width={88}
   104→          height={66}
   105→          style={styles.logo}
   106→        />
   107→        <Text font="Silkscreen-Regular" size={TextSize.medium}>
   108→          CLOAK
   109→        </Text>
   110→      </Block>
   111→    </ScreenLayout>
   112→  );
   113→};
   114→
