    61→    if (!userId) throw new Error("User ID not found");
    62→
    63→    const encryption = client.encryption();
    64→    const userIdentity = await encryption.userIdentity(userId, true);
    65→
    66→    return {
    67→      verificationState: encryption.verificationState(),
    68→      isVerified: VerificationService.isDeviceVerified(),
    69→      deviceId: VerificationService.getDeviceId(),
    70→      userIdentity: userIdentity
    71→        ? {
    72→            isVerified: userIdentity.isVerified(),
    73→            hasVerificationViolation: userIdentity.hasVerificationViolation(),
    74→            masterKey: userIdentity.masterKey(),
    75→          }
    76→        : null,
    77→    };
    78→  };
    79→
    80→  public static setupVerification = async (
    81→    onRequest: VerificationRequestCallback,
    82→    onEmojis: VerificationEmojisCallback,
    83→    onStateChange: VerificationStateChangeCallback,
    84→  ) => {
    85→    const client = MatrixCore.getClient();
    86→
    87→    VerificationService.onVerificationRequest = onRequest;
    88→    VerificationService.onVerificationEmojis = onEmojis;
    89→    VerificationService.onVerificationStateChange = onStateChange;
    90→
    91→    VerificationService.verificationController =
    92→      await client.getSessionVerificationController();
    93→
    94→    const delegate: SessionVerificationControllerDelegate = {
    95→      didReceiveVerificationRequest: (details: SessionVerificationRequestDetails) => {
    96→        console.log("📩 Verification request received:", details);
    97→        VerificationService.onVerificationStateChange?.("request");
    98→        VerificationService.onVerificationRequest?.(details);
    99→      },
   100→
   101→      didAcceptVerificationRequest: () => {
   102→        console.log("✅ Verification request accepted");
   103→        VerificationService.onVerificationStateChange?.("accepted");
   104→      },
   105→
   106→      didStartSasVerification: () => {
   107→        console.log("🔐 SAS verification started");
   108→        VerificationService.onVerificationStateChange?.("sasStarted");
   109→      },
   110→
   111→      didReceiveVerificationData: (data: SessionVerificationData) => {
   112→        console.log("📊 Verification data received:", data);
   113→
   114→        if (data.tag === SessionVerificationData_Tags.Emojis) {
   115→          const emojis = data.inner.emojis.map((emoji) => ({
   116→            symbol: emoji.symbol(),
   117→            description: emoji.description(),
   118→          }));
   119→          console.log("🎭 Emojis:", emojis);
   120→          VerificationService.onVerificationStateChange?.("emojis");
   121→          VerificationService.onVerificationEmojis?.(emojis);
   122→        } else if (data.tag === SessionVerificationData_Tags.Decimals) {
   123→          console.log("🔢 Decimals:", data.inner.values);
   124→        }
   125→      },
   126→
   127→      didFail: () => {
   128→        console.log("❌ Verification failed");
   129→        VerificationService.onVerificationStateChange?.("failed");
   130→      },
   131→
   132→      didCancel: () => {
   133→        console.log("🚫 Verification cancelled");
   134→        VerificationService.onVerificationStateChange?.("cancelled");
   135→      },
   136→
   137→      didFinish: () => {
   138→        console.log("🎉 Verification finished successfully!");
   139→        VerificationService.onVerificationStateChange?.("success");
   140→      },
   141→    };
   142→
   143→    VerificationService.verificationController.setDelegate(delegate);
   144→    console.log("✅ Verification controller set up successfully");
   145→  };
