### 4. **EncryptionService Methods**

**File:** `/Users/stjepandzojic/projects/cloakanddagger/src/modules/encryption/service/EncryptionService.ts`

**Key methods:**

```typescript
// Check if recovery is enabled
public static isRecoveryEnabled = async () => {
  if (!MatrixCore.instance) return false;
  const backupState = await EncryptionService.getBackupState();
  const recoveryState = await EncryptionService.getRecoveryState();
  const backupExists = backupState === "enabled";
  const recoveryDisabled = recoveryState === RecoveryState.Disabled;
  return backupExists && !recoveryDisabled;
};

// Reset identity (wipe encryption keys)
public static resetIdentity = async () => {
  await MatrixCore.getClient().encryption().resetIdentity();
  console.log("✅ Identity reset successfully");
};

// Get recovery state
public static getRecoveryState = async () => {
  const client = MatrixCore.getClient();
  await client.encryption().waitForE2eeInitializationTasks();
  return client.encryption().recoveryState();
};

// Get backup state
public static getBackupState = async (): Promise<MappedBackupState> => {
  const client = MatrixCore.getClient();
  await client.encryption().waitForE2eeInitializationTasks();
  const backupExists = await client.encryption().backupExistsOnServer();
  return backupExists ? "enabled" : "unknown";
};
```

