### 5. **ConfirmIdentity Screen Logic**

**File:** `/Users/stjepandzojic/projects/cloakanddagger/src/screens/confirm-identity/ConfirmIdentity.tsx`

```typescript
export const ConfirmIdentity: FC<NativeStackScreenProps<Routes, "confirmIdentity">> = ({ navigation }) => {
  const [loading, setLoading] = useState(true);
  const [hasOtherDevices, setHasOtherDevices] = useState(false);
  const [recoveryEnabled, setRecoveryEnabled] = useState(false);

  useEffect(() => {
    const checkSituation = async () => {
      try {
        const [otherDevices, recovery] = await Promise.all([
          VerificationService.hasDevicesToVerifyAgainst(),
          EncryptionService.isRecoveryEnabled(),
        ]);
        setHasOtherDevices(otherDevices);
        setRecoveryEnabled(recovery);
      } catch (error) {
        console.error("Failed to check verification situation:", error);
      } finally {
        setLoading(false);
      }
    };
    checkSituation();
  }, []);

  const showResetOnly = !hasOtherDevices && !recoveryEnabled;

  // Renders options based on situation:
  // - If other devices exist: "Verify with Another Device"
  // - If recovery enabled: "Use Recovery Key"
  // - If neither: "Reset Identity" (only option)
  // - Otherwise: "Can't confirm identity?" button
};
```

**Screen shows different options based on:**
1. `hasOtherDevices` → Can verify with another device
2. `recoveryEnabled` → Can use recovery key
3. `showResetOnly` → Only reset option available

